import numpy as np
import logging
from typing import Any

logger = logging.getLogger(__name__)


def _is_empty(obj):
    """Check if object is empty (None, empty list, empty array)."""
    if obj is None:
        return True
    if isinstance(obj, list) and len(obj) == 0:
        return True
    if isinstance(obj, np.ndarray) and obj.size == 0:
        return True
    return False


class Solver:
    def solve(self, problem, **kwargs) -> Any:
        """
        Solves the matrix square root problem.

        Computes the principal matrix square root X such that X @ X = A.
        Optimized for speed using eigenvalue decomposition when possible.

        :param problem: A dictionary representing the matrix square root problem.
        :return: A dictionary with key "sqrtm" containing a dictionary with key:
                 "X": A list of lists representing the principal square root matrix X.
        """
        A = problem["matrix"]

        # Ensure A is a numpy array with complex dtype
        if not isinstance(A, np.ndarray):
            A = np.array(A, dtype=complex)
        else:
            A = A.astype(complex, copy=False)

        n = A.shape[0]

        try:
            # Try eigenvalue decomposition method first (often faster for diagonalizable matrices)
            X = self._sqrtm_eig(A, n)

            # Verify the solution quickly
            if self._verify_quick(X, A, n):
                return {"sqrtm": {"X": X.tolist()}}

            # If eig method fails verification, fall back to scipy
            import scipy.linalg
            X, _ = scipy.linalg.sqrtm(A, disp=False)
            return {"sqrtm": {"X": X.tolist()}}

        except Exception as e:
            logger.error(f"Matrix square root computation failed: {e}")
            try:
                import scipy.linalg
                X, _ = scipy.linalg.sqrtm(A, disp=False)
                return {"sqrtm": {"X": X.tolist()}}
            except Exception as e2:
                logger.error(f"Scipy fallback also failed: {e2}")
                return {"sqrtm": {"X": []}}

    def _sqrtm_eig(self, A, n):
        """Compute matrix square root using eigenvalue decomposition."""
        # Check if matrix is Hermitian (faster path with eigh)
        if self._is_hermitian(A):
            # Use eigh for Hermitian matrices - faster and more stable
            w, V = np.linalg.eigh(A)
            # Ensure we get the principal square root (non-negative real part eigenvalues)
            sqrt_w = np.sqrt(w.astype(complex))
            # For principal square root, use sqrt with non-negative real part
            # np.sqrt already gives the principal branch for complex numbers
            X = V @ np.diag(sqrt_w) @ V.conj().T
        else:
            # General eigenvalue decomposition
            w, V = np.linalg.eig(A)
            # Compute sqrt of eigenvalues (principal branch)
            sqrt_w = np.sqrt(w.astype(complex))
            # X = V @ diag(sqrt_w) @ V^-1
            V_inv = np.linalg.inv(V)
            X = V @ np.diag(sqrt_w) @ V_inv

        return X

    def _is_hermitian(self, A, rtol=1e-10, atol=1e-12):
        """Check if matrix is approximately Hermitian."""
        if A.shape[0] != A.shape[1]:
            return False
        return np.allclose(A, A.conj().T, rtol=rtol, atol=atol)

    def _verify_quick(self, X, A, n, rtol=1e-5, atol=1e-8):
        """Quick verification that X@X ≈ A."""
        try:
            X2 = X @ X
            return np.allclose(X2, A, rtol=rtol, atol=atol)
        except Exception:
            return False
